@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--ink:#eef3ff;--muted:#8793aa;--cyan:#62e8f4;--gold:#ffcf74;--rose:#ff667d;--panel:rgba(15,21,35,.88)}
*{box-sizing:border-box}
html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#080c15;color:var(--ink);font-family:Manrope,system-ui,sans-serif;user-select:none;-webkit-user-select:none;touch-action:none}
body{display:grid;place-items:center}
.game{position:relative;width:min(100vw,1600px);height:min(100dvh,1000px);min-height:500px;overflow:hidden;background:#0b1120;isolation:isolate}
.game:before{content:"";position:absolute;inset:0;pointer-events:none;z-index:2;background:linear-gradient(180deg,rgba(5,8,17,.4),transparent 16%,transparent 80%,rgba(5,8,17,.56));box-shadow:inset 0 0 140px rgba(0,0,0,.62)}
canvas{position:absolute;inset:0;width:100%;height:100%;display:block}
.topbar{position:absolute;z-index:4;left:34px;right:34px;top:24px;display:flex;align-items:flex-start;justify-content:space-between;pointer-events:none}
.brand{display:flex;gap:12px;align-items:center}
.sigil{width:37px;height:37px;border:1px solid rgba(98,232,244,.55);display:grid;place-items:center;color:var(--cyan);font-size:20px;transform:rotate(45deg);background:rgba(15,25,40,.75);box-shadow:0 0 22px #62e8f422}
.sigil span{transform:rotate(-45deg)}
.brand-title{font-size:12px;letter-spacing:.24em;font-weight:800}
.brand-sub{font:9px 'DM Mono',monospace;color:#7f91ac;letter-spacing:.17em;margin-top:4px}
.encounter{text-align:center;position:absolute;left:50%;transform:translateX(-50%);top:3px}
.eyebrow{font:9px 'DM Mono',monospace;letter-spacing:.26em;color:#a6b0c2}
.encounter h1{font-size:19px;letter-spacing:.2em;margin:4px 0 0;font-weight:700}
.run-actions{display:flex;gap:8px;pointer-events:auto}
.icon-button{width:36px;height:36px;border:1px solid #ffffff22;background:#0b1222bb;color:#aab8ca;border-radius:4px;cursor:pointer;font-size:15px}
.icon-button:hover{border-color:#62e8f477;color:var(--cyan)}
.boss-hud{position:absolute;z-index:3;top:92px;left:50%;transform:translateX(-50%);width:min(430px,48vw);text-align:center;pointer-events:none}
.boss-name{font:10px 'DM Mono',monospace;letter-spacing:.23em;color:#e5e9f4;text-transform:uppercase}
.boss-sub{font-size:9px;color:#8f9aaf;letter-spacing:.1em;margin-top:4px}
.bar{height:8px;background:#1a2030;border:1px solid rgba(255,255,255,.1);margin-top:11px;position:relative;overflow:hidden}
.bar-fill{height:100%;width:100%;transition:width .22s ease;background:linear-gradient(90deg,#c43759,#ff7485);box-shadow:0 0 16px #fc627b88}
.bar-ticks{position:absolute;inset:0;background:repeating-linear-gradient(90deg,transparent 0,transparent calc(25% - 1px),#101522aa calc(25% - 1px),#101522aa 25%)}
.boss-readout{font:9px 'DM Mono',monospace;color:#bdc5d3;margin-top:5px}
.left-hud{position:absolute;left:34px;bottom:140px;width:210px;z-index:3}
.hero-label{font:9px 'DM Mono',monospace;color:#a4b2c7;letter-spacing:.18em;margin-bottom:8px}
.player-bar{height:7px;background:#1a2030;overflow:hidden}
.player-fill{height:100%;width:100%;background:linear-gradient(90deg,#20b9b6,#73f0cf);transition:width .2s}
.resource-row{display:flex;justify-content:space-between;align-items:center;margin-top:10px;font:9px 'DM Mono',monospace;color:#9daac0}
.resource-track{width:112px;height:4px;background:#222839;margin-left:8px;flex:1}
.resource-fill{height:100%;width:0;background:linear-gradient(90deg,#7f68ff,#c9a4ff);box-shadow:0 0 10px #a58aff}
.resource-number{color:#d8c8ff;margin-left:8px}
.bottom-ui{position:absolute;z-index:5;bottom:22px;left:50%;transform:translateX(-50%);display:flex;align-items:flex-end;gap:17px}
.skill-group{display:flex;gap:8px;align-items:flex-end}
.skill-card{position:relative;width:65px;height:74px;border:1px solid #ffffff26;background:linear-gradient(150deg,#1d2739ee,#111827f2);border-radius:5px;color:#e8effb;display:flex;flex-direction:column;align-items:center;justify-content:center;cursor:pointer;box-shadow:0 7px 25px #0005;transition:transform .12s,border-color .12s,filter .12s;touch-action:manipulation}
.skill-card:hover:not(.cooling){transform:translateY(-4px);border-color:#62e8f4aa}
.skill-card:active{transform:scale(.94)}
.skill-card .key{position:absolute;top:5px;left:6px;color:#8694aa;font:9px 'DM Mono',monospace}
.skill-card .glyph{font-size:23px;line-height:25px;text-shadow:0 0 12px currentColor}
.skill-card .skill-name{font-size:8px;font-weight:700;letter-spacing:.08em;margin-top:3px;color:#b9c5d8}
.skill-card .cooldown{position:absolute;inset:0;background:rgba(4,8,16,.72);display:none;align-items:center;justify-content:center;font:15px 'DM Mono',monospace;color:#fff}
.skill-card.cooling .cooldown{display:flex}
.skill-card.cooling{filter:saturate(.55)}
.ultimate-card{width:74px;height:82px;border-color:#a88aff69;background:linear-gradient(155deg,#30234c,#17182c);box-shadow:0 0 24px #957aff20}
.ultimate-card .glyph{font-size:27px;color:#d0a8ff}
.ultimate-card .skill-name{color:#d9c6ff}
.ultimate-card.ready{border-color:#d6a8ff;box-shadow:0 0 22px #b580ff66;animation:ultPulse 1.5s infinite}
.ultimate-card:not(.ready){filter:saturate(.5);opacity:.8}
.ultimate-card .charge{position:absolute;bottom:0;left:0;height:3px;background:#c092ff;transition:width .2s}
.@keyframes ultPulse{50%{box-shadow:0 0 30px #b580ffaa}
}
.combat-tip{position:absolute;bottom:110px;left:50%;transform:translateX(-50%);font:9px 'DM Mono',monospace;color:#94a1b6;letter-spacing:.06em;white-space:nowrap;z-index:3;text-shadow:0 1px 5px #000}
.toast{position:absolute;z-index:8;left:50%;top:34%;transform:translate(-50%,-50%);font:10px 'DM Mono',monospace;letter-spacing:.2em;color:#fff;background:#111b2bd9;border:1px solid #ffffff30;padding:10px 18px;opacity:0;transition:opacity .2s;pointer-events:none}
.toast.show{opacity:1}
.overlay{position:absolute;inset:0;z-index:10;display:flex;align-items:center;justify-content:center;background:radial-gradient(ellipse at 50% 45%,rgba(8,13,25,.22),rgba(4,7,14,.82));backdrop-filter:blur(4px);transition:opacity .35s}
.overlay.hidden{opacity:0;pointer-events:none}
.intro-card{width:min(510px,90vw);text-align:center;padding:35px 40px 32px;background:linear-gradient(145deg,#111b2beF,#0a101df2);border:1px solid #b9d1ed30;box-shadow:0 25px 100px #000a;position:relative}
.intro-card:before,.intro-card:after{content:"";position:absolute;width:25px;height:25px;border-color:#65dce8;border-style:solid}
.intro-card:before{top:-1px;left:-1px;border-width:1px 0 0 1px}
.intro-card:after{right:-1px;bottom:-1px;border-width:0 1px 1px 0}
.intro-mark{font:10px 'DM Mono',monospace;letter-spacing:.32em;color:var(--cyan)}
.intro-card h2{font-size:clamp(34px,6vw,51px);line-height:1;margin:16px 0 10px;letter-spacing:.04em}
.intro-card h2 span{color:#ff788b}
.intro-desc{color:#aab5c6;font-size:13px;line-height:1.75;max-width:380px;margin:0 auto 20px}
.mission{border-top:1px solid #ffffff14;border-bottom:1px solid #ffffff14;display:grid;grid-template-columns:1fr 1fr;padding:12px 0;margin:20px 0;text-align:left;gap:10px}
.mission div{font:9px 'DM Mono',monospace;color:#8794a9;letter-spacing:.08em}
.mission b{display:block;color:#e2e8f1;font-size:10px;margin-bottom:4px}
.start-button{background:#70e4e6;color:#07141b;border:0;padding:13px 30px;font:800 10px Manrope,sans-serif;letter-spacing:.18em;cursor:pointer;box-shadow:0 0 22px #62e8f444}
.start-button:hover{background:#a0f4ee;transform:translateY(-1px)}
.intro-foot{font:9px 'DM Mono',monospace;color:#718096;margin-top:14px}
.result-card{width:min(420px,90vw)}
.result-card h2{font-size:34px}
.touch-pad{display:none;position:absolute;z-index:4;bottom:24px;left:20px;width:110px;height:110px;border:1px solid #ffffff30;background:#0c13217a;border-radius:50%;touch-action:none}
.touch-knob{position:absolute;width:42px;height:42px;left:33px;top:33px;border-radius:50%;background:#79e6e477;border:1px solid #8cf9f0aa;box-shadow:0 0 18px #65e8e455}
.sound-off{color:#ffb4bc}

@media(max-width:700px){.game{min-height:100dvh}
.topbar{left:16px;right:16px;top:15px}
.sigil{width:30px;height:30px;font-size:16px}
.brand-title{font-size:10px}
.brand-sub{font-size:7px}
.encounter{top:48px}
.encounter h1{font-size:15px}
.eyebrow{font-size:8px}
.boss-hud{top:99px;width:72vw}
.left-hud{left:16px;bottom:150px;width:155px}
.bottom-ui{bottom:max(15px,env(safe-area-inset-bottom));gap:7px}
.skill-group{gap:4px}
.skill-card{width:49px;height:63px}
.skill-card .glyph{font-size:19px}
.skill-card .skill-name{font-size:7px}
.ultimate-card{width:55px;height:70px}
.ultimate-card .glyph{font-size:23px}
.combat-tip{bottom:95px;font-size:8px}
.touch-pad{display:block}
.run-actions{gap:5px}
.icon-button{width:32px;height:32px}
.intro-card{padding:28px 22px}
.intro-desc{font-size:12px}
.mission{margin:15px 0;padding:10px 0}
.toast{top:29%}
}

@media(max-width:390px){.bottom-ui{left:35%;transform:none;gap:3px}
.skill-group{gap:2px}
.skill-card{width:35px;height:59px}
.ultimate-card{width:44px;height:66px}
.skill-card .skill-name{font-size:6px;letter-spacing:0}
.left-hud{bottom:140px;width:130px}
}
@media(max-width:350px){.bottom-ui{left:98px}
.skill-card{width:32px}
.ultimate-card{width:41px}
}

