(() => {
'use strict';
const canvas=document.getElementById('scene'),ctx=canvas.getContext('2d'),$=id=>document.getElementById(id);
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a),TAU=Math.PI*2;
const heroes=[
 {id:'aegis',name:'AEGIS',role:'VANGUARD',icon:'⬟',color:'#67e8df',hp:1200,speed:210,damage:1,skills:['MOONCUT','STAR LANCE','NOVA BURST','RIFT STEP','WARDING VEIL'],glyphs:['☽','➤','✺','⌁','⬡'],cd:[3.2,2.1,7,5,10],ult:'CELESTIAL BREAK'},
 {id:'volt',name:'VOLT',role:'STRIKER',icon:'ϟ',color:'#ffd36d',hp:880,speed:270,damage:1.18,skills:['ARC SHOT','FLASH KICK','CHAIN NOVA','BLINK DRIVE','OVERCHARGE'],glyphs:['ϟ','➤','✦','⌁','⚡'],cd:[2.4,4.2,7.5,4.5,9],ult:'THUNDER GOD'},
 {id:'bastion',name:'BASTION',role:'GUARDIAN',icon:'◈',color:'#8cb8ff',hp:1500,speed:185,damage:.9,skills:['PULSE HAMMER','AEGIS BOLT','QUAKE','BULWARK DASH','REPAIR FIELD'],glyphs:['◈','➤','✺','⬡','✚'],cd:[3.5,2.5,8,5,11],ult:'FORTRESS FALL'},
 {id:'wisp',name:'WISP',role:'VOID MAGE',icon:'✧',color:'#c7a2ff',hp:940,speed:230,damage:1.1,skills:['RIFT SLASH','SOUL BOLT','SINGULARITY','PHASE SHIFT','ECLIPSE VEIL'],glyphs:['☽','✧','◉','⌁','⬡'],cd:[3,2,8,4.5,10],ult:'BLACK SUN'},
 {id:'flare',name:'FLARE',role:'BLASTER',icon:'✹',color:'#ff9d87',hp:1020,speed:225,damage:1.05,skills:['EMBER WAVE','SOLAR SPEAR','SUNBURST','JET STEP','PHOENIX VEIL'],glyphs:['✹','➤','☼','⌁','♨'],cd:[3.3,2.3,7,4.7,10],ult:'SUPERNOVA'},
 {id:'echo',name:'ECHO',role:'SUPPORT',icon:'⌁',color:'#83e9b9',hp:1080,speed:235,damage:.98,skills:['SONIC EDGE','RESONANCE','FEEDBACK','PHASE DODGE','HARMONIC AEGIS'],glyphs:['⌁','◖','✺','⌁','⬡'],cd:[3.1,2.2,7.3,4.5,9.5],ult:'AMPLIFY'}
];
const missions=[
 {name:'THE HOLLOW KING',area:'ECLIPSE SANCTUM',boss:'THE HOLLOW KING',enemy:'VOID WRAITH',color:'#d95776',desc:'Break the siege at the edge of the dying star.'},
 {name:'IRON TIDE',area:'ABYSSAL FOUNDRY',boss:'DREADNAUGHT PRIME',enemy:'FORGE DRONE',color:'#ff9b5b',desc:'Shut down the war machine before it reaches orbit.'},
 {name:'FROSTLINE',area:'CRYO-9 RELAY',boss:'THE PALE REGENT',enemy:'SHARD STALKER',color:'#73b9ff',desc:'Purge the frozen relay and face its ancient keeper.'}
];
let save={levels:{},completed:0};try{save={...save,...JSON.parse(localStorage.getItem('starfall-save')||'{}')}}catch(e){}
const keys={},state={w:0,h:0,dpr:1,started:false,paused:false,over:false,clock:0,mission:0,wave:0,team:['aegis','volt','bastion'],selected:'aegis',hero:null,enemies:[],projectiles:[],effects:[],hazards:[],cooldowns:[0,0,0,0,0],ult:0,shake:0,score:0,elapsed:0};
let arena={cx:0,cy:0,rx:0,ry:0},move={x:0,y:0},touching=false,last=0,audio;
const heroData=id=>heroes.find(h=>h.id===id),level=id=>Math.max(1,save.levels[id]||1);
function addStyles(){const s=document.createElement('style');s.textContent=`
.team-strip{position:absolute;z-index:5;left:34px;top:158px;display:flex;gap:7px;pointer-events:auto}.team-slot{width:74px;padding:7px 8px;background:#0d1625df;border:1px solid #ffffff24;color:#cbd6e5;text-align:left;cursor:pointer;font:8px 'DM Mono',monospace;position:relative}.team-slot b{display:block;font:800 10px Manrope,sans-serif;letter-spacing:.08em;margin-top:3px}.team-slot .slot-icon{font-size:17px;float:left;margin-right:6px;color:var(--slot)}.team-slot.active{border-color:var(--slot);box-shadow:0 0 16px color-mix(in srgb,var(--slot) 30%,transparent)}.team-slot .slot-hp{height:2px;background:#263044;margin-top:6px}.team-slot .slot-hp i{display:block;height:100%;background:var(--slot)}.stage-chip{position:absolute;z-index:3;left:34px;top:112px;color:#a7b6c8;font:9px 'DM Mono',monospace;letter-spacing:.12em}.objective-chip{position:absolute;z-index:3;right:34px;top:112px;color:#b6c6d8;font:9px 'DM Mono',monospace;letter-spacing:.1em;text-align:right}.select-wrap{margin:18px 0 16px;text-align:left}.select-label{font:9px 'DM Mono',monospace;letter-spacing:.18em;color:#95a7be;margin:13px 0 8px}.stage-options{display:flex;gap:6px}.stage-option{flex:1;background:#0c1421;border:1px solid #ffffff22;color:#acb8c8;padding:8px 4px;cursor:pointer;font:8px 'DM Mono',monospace}.stage-option.selected{border-color:#62e8f4;color:#e5ffff;background:#10252d}.roster{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.hero-option{min-width:0;background:#101827;border:1px solid #ffffff20;color:#eaf1fa;padding:8px 5px 7px;cursor:pointer;text-align:center;position:relative}.hero-option.selected{border-color:var(--hc);box-shadow:inset 0 0 16px color-mix(in srgb,var(--hc) 15%,transparent)}.hero-option .face{font-size:20px;display:block;color:var(--hc);line-height:24px}.hero-option b{display:block;font:800 9px Manrope,sans-serif;letter-spacing:.08em}.hero-option small{font:7px 'DM Mono',monospace;color:#91a0b5}.hero-option .picked{position:absolute;right:3px;top:3px;color:var(--hc);font:8px 'DM Mono',monospace}.select-hint{margin-top:8px;color:#7e8da3;font:8px 'DM Mono',monospace;text-align:center}.combat-tip{max-width:90vw;text-align:center}.result-reward{font:10px 'DM Mono',monospace;color:#ffdc91;letter-spacing:.15em;margin:4px 0 18px}.start-button:disabled{opacity:.42;cursor:not-allowed}.skill-card .skill-name{max-width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.boss-hud.boss-hidden{opacity:.25}.result-actions{display:flex;justify-content:center;gap:8px}.result-actions .start-button.secondary{background:transparent;color:#c9d4e5;border:1px solid #ffffff35;box-shadow:none}.objective-complete{color:#8bf0d0!important}
@media(max-width:700px){.team-strip{left:13px;top:156px;gap:4px}.team-slot{width:60px;padding:5px}.team-slot b{font-size:8px}.stage-chip{left:15px;top:137px;font-size:7px}.objective-chip{right:15px;top:137px;font-size:7px}.select-wrap{margin:12px 0}.roster{gap:4px}.hero-option{padding:5px 2px}.hero-option .face{font-size:17px}.hero-option b{font-size:8px}.hero-option small{font-size:6px}.stage-option{font-size:7px;padding:7px 2px}}
`;document.head.appendChild(s)}
addStyles();
function installUI(){const strip=document.createElement('div');strip.className='team-strip';strip.id='teamStrip';$('game').appendChild(strip);const stage=document.createElement('div');stage.className='stage-chip';stage.id='stageChip';$('game').appendChild(stage);const obj=document.createElement('div');obj.className='objective-chip';obj.id='objectiveChip';$('game').appendChild(obj);
 const intro=$('intro').querySelector('.intro-card'),start=$('startBtn');const selection=document.createElement('div');selection.className='select-wrap';selection.id='selectWrap';selection.innerHTML='<div class="select-label">SELECT OPERATION</div><div class="stage-options" id="stageOptions"></div><div class="select-label">BUILD YOUR THREE-HERO STRIKE TEAM</div><div class="roster" id="roster"></div><div class="select-hint">SELECT ANY THREE · TAP A HERO AGAIN TO REMOVE</div>';intro.insertBefore(selection,start);
 const foot=intro.querySelector('.intro-foot');if(foot)foot.textContent='WASD / ARROWS MOVE · SPACE DODGE · 1–5 SKILLS · Q ULTIMATE · F1–F3 SWITCH';
 const result=$('result').querySelector('.result-card');const reward=document.createElement('div');reward.className='result-reward';reward.id='rewardText';const next=document.createElement('button');next.className='start-button';next.id='nextBtn';next.textContent='NEXT OPERATION  →';next.style.display='none';result.append(reward,next);next.addEventListener('click',()=>{state.mission=(state.mission+1)%missions.length;showIntro()});
 for(let i=0;i<5;i++){const b=document.createElement('button');b.className='skill-card';b.dataset.action='skill'+i;b.innerHTML=`<span class="key">${i+1}</span><span class="glyph"></span><span class="skill-name"></span><span class="cooldown"></span>`;$('skills').appendChild(b);b.addEventListener('pointerdown',e=>{e.preventDefault();useSkill(i)})}
 $('ultBtn').addEventListener('pointerdown',e=>{e.preventDefault();useUlt()});$('startBtn').addEventListener('click',startMission);$('retryBtn').addEventListener('click',()=>showIntro());$('pauseBtn').addEventListener('click',()=>{if(!state.started)return;state.paused=!state.paused;$('pauseBtn').textContent=state.paused?'▶':'Ⅱ';toast(state.paused?'PAUSED':'RESUME')});$('soundBtn').addEventListener('click',()=>{sound=!sound;$('soundBtn').textContent=sound?'♫':'♪';toast(sound?'SOUND ON':'SOUND OFF')});
 drawSelection();updateHud();}
let sound=true;
function drawSelection(){const stage=$('stageOptions'),roster=$('roster');stage.innerHTML='';missions.forEach((m,i)=>{const b=document.createElement('button');b.className='stage-option'+(i===state.mission?' selected':'');b.innerHTML=`0${i+1} · ${m.area}`;b.onclick=()=>{state.mission=i;drawSelection()};stage.append(b)});roster.innerHTML='';heroes.forEach(h=>{const picked=state.team.includes(h.id),b=document.createElement('button');b.className='hero-option'+(picked?' selected':'');b.style.setProperty('--hc',h.color);b.innerHTML=`<span class="picked">${picked?String(state.team.indexOf(h.id)+1):''}</span><span class="face">${h.icon}</span><b>${h.name}</b><small>${h.role} · LV ${level(h.id)}</small><small>${h.hp+((level(h.id)-1)*45)} HP</small>`;b.onclick=()=>{if(picked){if(state.team.length>1)state.team=state.team.filter(id=>id!==h.id)}else if(state.team.length<3)state.team.push(h.id);else toast('TEAM IS FULL — REMOVE A HERO FIRST');drawSelection()};roster.append(b)});$('startBtn').disabled=state.team.length!==3}
function showIntro(){state.started=false;state.paused=false;state.over=false;$('result').classList.add('hidden');$('intro').classList.remove('hidden');$('selectWrap').style.display='block';$('startBtn').style.display='inline-block';$('retryBtn').style.display='none';$('nextBtn').style.display='none';const m=missions[state.mission];document.querySelector('.encounter h1').textContent=m.name;$('intro').querySelector('h2').innerHTML=m.name==='THE HOLLOW KING'?'THE HOLLOW <span>KING</span>':m.name.split(' ')[0]+' <span>'+m.name.split(' ').slice(1).join(' ')+'</span>';document.querySelector('.intro-desc').textContent=m.desc;document.querySelector('.mission').innerHTML=`<div><b>MISSION OBJECTIVE</b>Clear 2 enemy waves, then defeat ${m.boss}.</div><div><b>VICTORY REWARD</b>XP, star shards & hero levels.</div>`;drawSelection();}
function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),1050)}
function resize(){const r=$('game').getBoundingClientRect();state.w=r.width;state.h=r.height;state.dpr=Math.min(devicePixelRatio||1,2);canvas.width=state.w*state.dpr;canvas.height=state.h*state.dpr;ctx.setTransform(state.dpr,0,0,state.dpr,0,0);arena={cx:state.w/2,cy:state.h*.53,rx:Math.min(state.w*.39,610),ry:Math.min(state.h*.36,330)};if(state.hero){state.hero.x=clamp(state.hero.x,arena.cx-arena.rx*.82,arena.cx+arena.rx*.82);state.hero.y=clamp(state.hero.y,arena.cy-arena.ry*.78,arena.cy+arena.ry*.78)}}window.addEventListener('resize',resize);resize();
function playTone(freq=400,dur=.08){if(!sound)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=freq;g.gain.value=.025;o.connect(g);g.connect(audio.destination);o.start();g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.stop(audio.currentTime+dur)}catch(e){}}
function emit(x,y,color,n=12,power=100){for(let i=0;i<n;i++){const a=rand(0,TAU),v=rand(power*.25,power);state.effects.push({kind:'particle',x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:rand(.25,.65),color,size:rand(2,5)})}}
function ring(x,y,color,r=100){state.effects.push({kind:'ring',x,y,r:5,max:r,life:.42,maxLife:.42,color})}
function textFloat(x,y,text,color='#fff'){state.effects.push({kind:'text',x,y,text,color,life:.8,maxLife:.8})}

function startMission(){if(state.team.length!==3)return;state.actors=state.team.map((id,i)=>{const d=heroData(id),lv=level(id),max=d.hp+(lv-1)*45;return{id,data:d,level:lv,maxHp:max,hp:max,charge:0,x:arena.cx+(i-1)*35,y:arena.cy+arena.ry*.58,invuln:0,shield:0,face:-Math.PI/2,dash:0}});state.active=0;state.hero=state.actors[0];state.wave=0;state.enemies=[];state.projectiles=[];state.effects=[];state.hazards=[];state.elapsed=0;state.score=0;state.cooldowns=[0,0,0,0,0];state.ult=0;state.over=false;state.paused=false;state.started=true;$('intro').classList.add('hidden');$('result').classList.add('hidden');$('pauseBtn').textContent='Ⅱ';state.hero.x=arena.cx;state.hero.y=arena.cy+arena.ry*.55;spawnWave();refreshSkills();updateHud();toast('OPERATION '+String(state.mission+1).padStart(2,'0')+' — DEPLOYED');playTone(480,.18)}
function spawnWave(){state.wave++;state.enemies=[];const boss=state.wave>2,m=missions[state.mission],count=boss?1:3;for(let i=0;i<count;i++){const angle=boss?-Math.PI/2:Math.PI*2*i/count+rand(-.25,.25),distance=boss?.30:rand(.46,.69),x=arena.cx+Math.cos(angle)*arena.rx*distance,y=arena.cy+Math.sin(angle)*arena.ry*distance;const max=boss?1800+state.mission*500:300+state.mission*90;state.enemies.push({x,y,r:boss?40:19,hp:max,maxHp:max,boss,kind:boss?m.boss:m.enemy,color:m.color,attack:rand(1.3,2.2),wind:0,flash:0,stagger:0,seed:rand(0,6),speed:boss?38:68+state.mission*4})}updateHud()}
function refreshSkills(){const d=state.hero.data;document.querySelectorAll('#skills .skill-card').forEach((el,i)=>{el.querySelector('.glyph').textContent=d.glyphs[i];el.querySelector('.glyph').style.color=d.color;el.querySelector('.skill-name').textContent=d.skills[i];el.querySelector('.key').textContent=i===3?'SPACE':String(i+1);el.title=d.skills[i]});$('ultBtn').querySelector('.skill-name').textContent=d.ult;$('ultBtn').querySelector('.glyph').style.color=d.color;}
function switchHero(i){if(!state.started||state.paused||!state.actors||!state.actors[i]||i===state.active)return;state.active=i;state.hero=state.actors[i];state.hero.invuln=Math.max(state.hero.invuln,.35);state.cooldowns=state.hero.cooldowns||(state.hero.cooldowns=[0,0,0,0,0]);state.ult=state.hero.ult||0;refreshSkills();updateHud();toast('SWITCH // '+state.hero.data.name);emit(state.hero.x,state.hero.y,state.hero.data.color,10,75);playTone(600,.08)}
function buildTeamHud(){const root=$('teamStrip');root.innerHTML='';(state.actors||[]).forEach((a,i)=>{const b=document.createElement('button');b.className='team-slot'+(i===state.active?' active':'');b.style.setProperty('--slot',a.data.color);b.innerHTML=`<span class="slot-icon">${a.data.icon}</span><small>F${i+1} · LV${a.level}</small><b>${a.data.name}</b><div class="slot-hp"><i style="width:${100*a.hp/a.maxHp}%"></i></div>`;b.onclick=()=>switchHero(i);root.append(b)})}
function updateHud(){const hero=state.hero;if(hero){const pct=100*hero.hp/hero.maxHp;$('playerFill').style.width=pct+'%';$('playerHpText').textContent=`${Math.ceil(hero.hp).toLocaleString()} / ${hero.maxHp.toLocaleString()}`;$('chargeFill').style.width=hero.charge+'%';$('chargeText').textContent=Math.floor(hero.charge)+'%';$('ultCharge').style.width=hero.charge+'%';$('ultBtn').classList.toggle('ready',hero.charge>=100);document.querySelector('.hero-label').textContent=`✧  ${hero.data.name} · LV ${hero.level} · ${hero.data.role}`;}
 const target=state.enemies?.find(e=>e.boss)||state.enemies?.[0],hud=document.querySelector('.boss-hud');if(target){hud.classList.toggle('boss-hidden',!target.boss);document.querySelector('.boss-name').textContent='✦  '+target.kind+'  ✦';document.querySelector('.boss-sub').textContent=target.boss?'ELITE // VOID-CROWNED':'HOSTILE // '+String(state.enemies.length).padStart(2,'0')+' REMAINING';$('bossFill').style.width=(100*target.hp/target.maxHp)+'%';$('bossHpText').textContent=Math.ceil(target.hp).toLocaleString();document.querySelector('.boss-readout span:last-child').textContent='/ '+target.maxHp.toLocaleString()}else{$('bossFill').style.width='0%'}
 $('stageChip').textContent=state.started?`STAGE 0${state.mission+1} / ${missions[state.mission].area} · WAVE ${Math.min(state.wave,3)}/3`:'';$('objectiveChip').textContent=state.started?(state.wave<3?`OBJECTIVE · CLEAR ENEMIES (${state.enemies.length})`:`OBJECTIVE · DEFEAT ${missions[state.mission].boss}`):'';buildTeamHud();
 const cards=document.querySelectorAll('#skills .skill-card');cards.forEach((el,i)=>{const cd=state.cooldowns?.[i]||0;el.classList.toggle('cooling',cd>.02);el.querySelector('.cooldown').textContent=cd>.02?cd.toFixed(1):''});$('ultCooldown').textContent=state.ult>.02?state.ult.toFixed(1):'';}
function hurtEnemy(e,dmg,x=e.x,y=e.y){if(!state.started||e.hp<=0)return;e.hp=Math.max(0,e.hp-dmg);e.flash=.12;state.hero.charge=clamp(state.hero.charge+dmg*.035,0,100);textFloat(x,y-25,'-'+Math.round(dmg),'#ffe5a0');emit(x,y,e.color,7,60);state.shake=Math.max(state.shake,2);playTone(160+Math.random()*90,.06);if(e.hp<=0){emit(e.x,e.y,e.color,e.boss?44:22,e.boss?240:150);ring(e.x,e.y,e.color,e.boss?130:55);state.score+=e.boss?1000:100;if(e.boss){missionWon();return}state.enemies=state.enemies.filter(x=>x!==e);if(state.enemies.length===0){if(state.wave<3){toast('WAVE CLEARED — INCOMING');setTimeout(()=>{if(state.started)spawnWave()},900)}else spawnWave()} }updateHud()}
function damageHero(amount){const h=state.hero;if(!h||h.invuln>0||h.shield>0)return;h.hp=Math.max(0,h.hp-amount);h.invuln=.7;textFloat(h.x,h.y-26,'-'+amount,'#ff7789');emit(h.x,h.y,'#ff6078',12,105);state.shake=6;playTone(95,.14);if(h.hp<=0){const next=state.actors.findIndex((a,i)=>i!==state.active&&a.hp>0);if(next>=0){toast(h.data.name+' DOWN — TEAMMATE IN');setTimeout(()=>switchHero(next),350)}else missionLost()}updateHud()}
function nearestEnemy(){return state.enemies.reduce((best,e)=>!best||Math.hypot(e.x-state.hero.x,e.y-state.hero.y)<Math.hypot(best.x-state.hero.x,best.y-state.hero.y)?e:best,null)}
function attack(){if(!state.started||state.paused||state.over)return;const h=state.hero,e=nearestEnemy();if(!e)return;const dx=e.x-h.x,dy=e.y-h.y,d=Math.hypot(dx,dy)||1;h.face=Math.atan2(dy,dx);if(d>265){toast('TARGET OUT OF RANGE');return}if(d<95){const arc=state.hero.data.id==='bastion'?105:78;ring(h.x+dx/d*39,h.y+dy/d*39,h.data.color,arc);emit(h.x+dx/d*35,h.y+dy/d*35,h.data.color,8,90);hurtEnemy(e,92*h.data.damage*(1+(h.level-1)*.08),e.x,e.y)}else{state.projectiles.push({x:h.x,y:h.y,vx:dx/d*520,vy:dy/d*520,life:.72,damage:68*h.data.damage*(1+(h.level-1)*.08),color:h.data.color,r:6});emit(h.x+dx/d*15,h.y+dy/d*15,h.data.color,3,28)}playTone(540,.07)}
function useSkill(i){if(!state.started||state.paused||state.over)return;if(i===3){dodge();return}if(state.cooldowns[i]>0){toast('SKILL RECHARGING');return}const h=state.hero,d=h.data,e=nearestEnemy();if(!e)return;const dx=e.x-h.x,dy=e.y-h.y,dist=Math.hypot(dx,dy)||1,ux=dx/dist,uy=dy/dist,scale=d.damage*(1+(h.level-1)*.08);h.face=Math.atan2(dy,dx);state.cooldowns[i]=d.cd[i];h.cooldowns=state.cooldowns;
 if(i===0){const reach=d.id==='bastion'?155:130;ring(h.x+ux*55,h.y+uy*55,d.color,reach);for(const target of [...state.enemies])if(Math.hypot(target.x-h.x,target.y-h.y)<reach+target.r)hurtEnemy(target,145*scale,target.x,target.y);emit(h.x+ux*50,h.y+uy*50,d.color,18,140)}
 if(i===1){state.projectiles.push({x:h.x,y:h.y,vx:ux*640,vy:uy*640,life:1.15,damage:170*scale,color:d.color,r:9,seek:true});playTone(780,.12)}
 if(i===2){ring(h.x,h.y,d.color,230);emit(h.x,h.y,d.color,34,220);for(const target of [...state.enemies])if(Math.hypot(target.x-h.x,target.y-h.y)<235+target.r)hurtEnemy(target,230*scale,target.x,target.y);state.shake=5;playTone(250,.22)}
 if(i===4){const heal=Math.min(h.maxHp-h.hp,d.id==='bastion'?360:260);h.hp+=heal;h.shield=2.2;ring(h.x,h.y,d.color,135);emit(h.x,h.y,d.color,24,150);textFloat(h.x,h.y-32,'+'+heal+' RESTORED','#8df2c9');updateHud();playTone(650,.2)}updateHud()}
