function useUlt(){if(!state.started||state.paused||state.over||state.ult<100){toast(state.ult<100?'ULTIMATE NOT CHARGED':'');return}const p=state.hero,h=heroData(p.id);state.ult=0;state.shake=16;ring(p.x,p.y,p.color,Math.max(arena.rx,arena.ry)*.9);emit(p.x,p.y,p.color,70,290);for(const e of [...state.enemies]){const d=Math.hypot(e.x-p.x,e.y-p.y);if(d<Math.max(arena.rx,arena.ry)*1.1)damageEnemy(e,(e.boss?780:900)*p.damage)}p.hp=Math.min(p.max,p.hp+p.max*.2);p.invuln=1.1;state.hazards=[];toast(h.ult+' // RELEASED');playTone(110,.45);updateHud()}
function dodge(){if(!state.started||state.paused||state.over||state.hero.dodge>0)return;let dx=move.x,dy=move.y;if(!dx&&!dy){dx=Math.cos(state.hero.face);dy=Math.sin(state.hero.face)}const d=Math.hypot(dx,dy)||1;state.hero.x=clamp(state.hero.x+dx/d*110,arena.cx-arena.rx*.8,arena.cx+arena.rx*.8);state.hero.y=clamp(state.hero.y+dy/d*90,arena.cy-arena.ry*.76,arena.cy+arena.ry*.76);state.hero.invuln=.48;state.hero.dodge=1.25;emit(state.hero.x,state.hero.y,state.hero.color,13,130);playTone(700,.07)}
function hurtHero(amount){const p=state.hero;if(p.invuln>0)return;if(p.guard>0)amount*=.55;p.hp-=amount;p.invuln=.7;state.shake=7;emit(p.x,p.y,'#ff7388',12,120);textFloat(p.x,p.y-25,'-'+Math.round(amount),'#ff8192');const member=state.teamState[p.id];member.hp=Math.max(0,p.hp);if(p.hp<=0){member.alive=false;const next=state.team.findIndex((id,i)=>i!==state.activeSlot&&state.teamState[id].alive);if(next>=0){toast(`${heroData(p.id).name} // WARDEN DOWN`);switchHero(next)}else finish(false)}updateHud()}
function enemyAttack(e){if(e.attack>0||e.wind>0)return;const d=Math.hypot(state.hero.x-e.x,state.hero.y-e.y);if(e.boss){e.wind=1.05;e.phase++;const a=Math.atan2(state.hero.y-e.y,state.hero.x-e.x);state.hazards.push({x:state.hero.x,y:state.hero.y,r:62,life:.8,max:.8,color:e.color,kind:'target'});if(e.phase%3===0){for(let j=-1;j<=1;j++){const ang=a+j*.28;state.projectiles.push({x:e.x,y:e.y,vx:Math.cos(ang)*220,vy:Math.sin(ang)*220,damage:105,color:e.color,r:9,life:2,hostile:true})}}else state.projectiles.push({x:e.x,y:e.y,vx:Math.cos(a)*300,vy:Math.sin(a)*300,damage:125,color:e.color,r:10,life:2,hostile:true});return}e.wind=e.kind==='ranged'?.45:.38;if(e.kind==='ranged'){const a=Math.atan2(state.hero.y-e.y,state.hero.x-e.x);state.projectiles.push({x:e.x,y:e.y,vx:Math.cos(a)*260,vy:Math.sin(a)*260,damage:55,color:e.color,r:6,life:2,hostile:true})}else if(d<48)hurtHero(48)}

