function update(dt){if(!state.started||state.paused||state.over)return;state.clock+=dt;state.elapsed+=dt;const p=state.hero;p.invuln=Math.max(0,p.invuln-dt);p.guard=Math.max(0,p.guard-dt);p.dodge=Math.max(0,p.dodge-dt);p.attack=Math.max(0,p.attack-dt);state.cooldowns=state.cooldowns.map(c=>Math.max(0,c-dt));const mx=move.x+(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0),my=move.y+(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0),mag=Math.hypot(mx,my);if(mag>.05){p.x+=mx/mag*p.speed*dt;p.y+=my/mag*p.speed*dt;p.face=Math.atan2(my,mx)}p.x=clamp(p.x,arena.cx-arena.rx*.79,arena.cx+arena.rx*.79);p.y=clamp(p.y,arena.cy-arena.ry*.75,arena.cy+arena.ry*.75);for(const e of [...state.enemies]){e.flash=Math.max(0,e.flash-dt);e.wind=Math.max(0,e.wind-dt);e.attack=Math.max(0,e.attack-dt);const dx=p.x-e.x,dy=p.y-e.y,d=Math.hypot(dx,dy)||1;if(e.boss){const near=d<185,spd=near?36:78;e.x+=dx/d*spd*dt;e.y+=dy/d*spd*dt}else if(e.kind==='ranged'){if(d>270){e.x+=dx/d*75*dt;e.y+=dy/d*75*dt}else if(d<180){e.x-=dx/d*55*dt;e.y-=dy/d*55*dt}}else{e.x+=dx/d*88*dt;e.y+=dy/d*88*dt}if((e.kind==='melee'&&d<45)||e.kind==='ranged'&&d<420||e.boss&&d<560)enemyAttack(e)}for(let i=state.projectiles.length-1;i>=0;i--){const q=state.projectiles[i];q.x+=q.vx*dt;q.y+=q.vy*dt;q.life-=dt;if(q.hostile&&Math.hypot(q.x-p.x,q.y-p.y)<p.r+q.r){hurtHero(q.damage);state.projectiles.splice(i,1);continue}if(!q.hostile){let hit=null;for(const e of state.enemies)if(Math.hypot(q.x-e.x,q.y-e.y)<e.r+q.r){hit=e;break}if(hit){damageEnemy(hit,q.damage*p.damage);emit(q.x,q.y,q.color,5,80);state.projectiles.splice(i,1);continue}}if(q.life<=0||q.x<arena.cx-arena.rx||q.x>arena.cx+arena.rx||q.y<arena.cy-arena.ry||q.y>arena.cy+arena.ry)state.projectiles.splice(i,1)}for(let i=state.hazards.length-1;i>=0;i--){const z=state.hazards[i];z.life-=dt;if(z.life<=0){if(Math.hypot(p.x-z.x,p.y-z.y)<z.r+p.r)hurtHero(z.kind==='target'?120:80);ring(z.x,z.y,z.color,z.r);state.hazards.splice(i,1)}}for(let i=state.effects.length-1;i>=0;i--){const f=state.effects[i];f.life-=dt;if(f.kind==='particle'){f.x+=f.vx*dt;f.y+=f.vy*dt;f.vx*=.96;f.vy*=.96}if(f.life<=0)state.effects.splice(i,1)}updateHud()}
function finish(win){if(state.over)return;state.over=true;state.started=false;const title=$('resultTitle'),desc=$('resultDesc');$('resultMark').textContent=win?'✦  OPERATION COMPLETE  ✦':'✦  SIGNAL LOST  ✦';title.textContent=win?'VICTORY':'DEFEAT';title.style.color=win?'#83f0d0':'#ff8192';if(win){save.completed=Math.max(save.completed,state.mission+1);const earned=350+state.mission*150+Math.floor(state.elapsed*2);save.shards=(save.shards||0)+earned;state.team.forEach(id=>{const before=level(id);save.levels[id]=Math.min(20,before+1)});try{localStorage.setItem('starfall-save',JSON.stringify(save))}catch(e){}desc.textContent=`${missions[state.mission].boss} has fallen. ${earned} star shards secured. Strike team gained 1 level.`;$('nextBtn').style.display='inline-block';$('retryBtn').textContent='RUN OPERATION AGAIN  ↻'}else{desc.textContent='Your strike team has fallen. Regroup, change your lineup, and return to the arena.';$('nextBtn').style.display='none';$('retryBtn').textContent='RETURN TO BRIEFING  ↻'}$('rewardText').textContent=`✦  ${save.shards||0} STAR SHARDS  ·  OPERATIONS CLEARED ${save.completed||0}/3  ·  SCORE ${state.score}`;$('result').classList.remove('hidden');playTone(win?620:130,.3);updateHud()}
function updateHud(){const h=state.hero;if(h){$('playerFill').style.width=`${100*h.hp/h.max}%`;$('playerHpText').textContent=`${Math.max(0,Math.ceil(h.hp)).toLocaleString()} / ${h.max.toLocaleString()}`;$('chargeFill').style.width=`${state.ult}%`;$('chargeText').textContent=`${Math.floor(state.ult)}%`;const boss=state.enemies.find(e=>e.boss);if(boss){$('bossFill').style.width=`${100*boss.hp/boss.max}%`;$('bossHpText').textContent=Math.max(0,Math.ceil(boss.hp)).toLocaleString();const den=document.querySelector('.boss-readout span:last-child');if(den)den.textContent=`/ ${boss.max.toLocaleString()}`}}const strip=$('teamStrip');if(strip)strip.innerHTML=state.team.map((id,i)=>{const h=heroData(id),v=state.teamState?.[id],hp=v?v.hp:v?.max||0;return `<button class="team-slot ${i===state.activeSlot?'active':''}" style="--slot:${h.color}" data-slot="${i}" ${v&&!v.alive?'disabled':''}><span class="slot-icon">${h.icon}</span>${i+1}<b>${h.name}</b><div class="slot-hp"><i style="width:${v?Math.max(0,100*v.hp/v.max):0}%"></i></div></button>`}).join('');strip?.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>switchHero(+b.dataset.slot));$('stageChip').textContent=`OPERATION 0${state.mission+1}  //  ${missions[state.mission].area}`;$('objectiveChip').textContent=state.wave<2?`WAVE ${Math.max(1,state.wave)}  //  HOSTILES ${state.enemies.filter(e=>!e.boss).length}`:state.enemies.some(e=>e.boss)?`ELIMINATE  //  ${missions[state.mission].boss}`:'OPERATION COMPLETE';document.querySelectorAll('.skill-card[data-action^="skill"]').forEach((b,i)=>{const hero=heroData(h?.id||state.team[0]);b.querySelector('.glyph').textContent=hero.glyphs[i];b.querySelector('.skill-name').textContent=hero.skills[i];b.querySelector('.cooldown').textContent=state.cooldowns[i]>0?state.cooldowns[i].toFixed(1):'';b.classList.toggle('cooling',state.cooldowns[i]>0)});$('ultBtn').querySelector('.skill-name').textContent=heroData(h?.id||state.team[0]).ult;$('ultCharge').style.width=`${state.ult}%`;$('ultCooldown').textContent=state.ult>=100?'READY':'';$('ultBtn').classList.toggle('ready',state.ult>=100)}

