function bindInput(){window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Tab'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.repeat)return;if(e.code==='Space')dodge();if(e.code==='KeyJ'||e.code==='KeyK'||e.code==='Enter')basicAttack();if(e.code==='KeyQ')useUlt();if(e.code==='Digit1')useSkill(0);if(e.code==='Digit2')useSkill(1);if(e.code==='Digit3')useSkill(2);if(e.code==='Digit4')useSkill(3);if(e.code==='Digit5')useSkill(4);if(e.code==='F1')switchHero(0);if(e.code==='F2')switchHero(1);if(e.code==='F3')switchHero(2);if(e.code==='Tab')switchHero(((state.activeSlot||0)+1)%state.team.length);if(e.code==='Escape'&&state.started){state.paused=!state.paused;$('pauseBtn').textContent=state.paused?'▶':'Ⅱ'}});window.addEventListener('keyup',e=>{keys[e.code]=false});canvas.addEventListener('pointerdown',e=>{if(e.button===0){const r=canvas.getBoundingClientRect();const x=e.clientX-r.left,y=e.clientY-r.top;if(state.started&&x>state.w*.46&&y<state.h-125)basicAttack()}});const pad=$('touchPad'),knob=$('touchKnob');let padId=null;pad.addEventListener('pointerdown',e=>{e.preventDefault();padId=e.pointerId;pad.setPointerCapture(padId);touching=true;movePad(e)});pad.addEventListener('pointermove',e=>{if(e.pointerId===padId)movePad(e)});const end=e=>{if(e.pointerId!==padId)return;padId=null;touching=false;move={x:0,y:0};knob.style.transform='translate(0,0)'};pad.addEventListener('pointerup',end);pad.addEventListener('pointercancel',end);function movePad(e){const r=pad.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,max=r.width*.34,d=Math.hypot(dx,dy),scale=d>max?max/d:1;move={x:dx*scale/max,y:dy*scale/max};knob.style.transform=`translate(${dx*scale}px,${dy*scale}px)`}}
